package com.autoops.execution.engine;import com.autoops.command.repository.CommandDefinitionRepository;import com.autoops.command.service.SafeCommandResolver;import com.autoops.credential.repository.CredentialRepository;import com.autoops.credential.service.CredentialCryptoService;import com.autoops.execution.entity.*;import com.autoops.execution.preflight.PreflightService;import com.autoops.execution.realtime.ExecutionEventPublisher;import com.autoops.execution.repository.*;import com.autoops.infrastructure.remote.RemoteClient;import com.autoops.machine.repository.MachineRepository;import org.springframework.scheduling.annotation.Async;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.Map;@Service public class ExecutionEngine{private final MachineRepository machines;private final CredentialRepository credentials;private final CredentialCryptoService crypto;private final CommandDefinitionRepository commands;private final MachineRunRepository machineRuns;private final StepRunRepository steps;private final PreflightService preflight;private final RemoteClient remote;private final ExecutionEventPublisher events;public ExecutionEngine(MachineRepository m,CredentialRepository c,CredentialCryptoService x,CommandDefinitionRepository d,MachineRunRepository mr,StepRunRepository s,PreflightService p,RemoteClient r,ExecutionEventPublisher e){machines=m;credentials=c;crypto=x;commands=d;machineRuns=mr;steps=s;preflight=p;remote=r;events=e;}@Async public void runCommand(Long executionId,Long commandId,Long machineId,Long credentialId,String resolved){var mr=new MachineRun();mr.setExecutionId(executionId);mr.setMachineId(machineId);mr.setCredentialId(credentialId);mr.setStatus("RUNNING");mr=machineRuns.save(mr);events.publish(executionId,"MACHINE_STARTED",Map.of("machineId",machineId));preflight.run(mr.getId(),machineId,credentialId);var machine=machines.findById(machineId).orElseThrow();var cred=credentials.findById(credentialId).orElseThrow();var sr=new StepRun();sr.setMachineRunId(mr.getId());sr.setResolvedCommand(resolved);sr.setStatus("RUNNING");sr=steps.save(sr);events.publish(executionId,"STEP_STARTED",Map.of("stepRunId",sr.getId()));String pw=crypto.decrypt(cred.getEncryptedPassword(),cred.getEncryptionIv());var out=remote.execute(machine.getHostname(),machine.getSshPort(),cred.getUsername(),pw,resolved,60);sr.setStatus(out.success()?"SUCCESS":"FAILED");steps.save(sr);mr.setStatus(out.success()?"SUCCESS":"FAILED");machineRuns.save(mr);events.publish(executionId,"STEP_COMPLETED",Map.of("stepRunId",sr.getId(),"success",out.success(),"exitCode",out.exitCode()));}}
